"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    if not event_topic.startswith(subscribed_pattern):
        return False

    # If exact match, it's a valid subscription
    if len(event_topic) == len(subscribed_pattern):
        return True

    # Check for segment boundary to prevent prefix leaks (e.g., 'orders' matching 'orders_admin')
    next_char = event_topic[len(subscribed_pattern)]

    # If the subscription pattern already ends with a delimiter, any following character is valid
    if subscribed_pattern and subscribed_pattern[-1] in (":", "/", "."):
        return True

    # Otherwise, the next character must be a delimiter to ensure we're at a topic boundary
    return next_char in (":", "/", ".")

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
